            active_border   = colors.accent,
            inactive_border = "rgba(00000000)",
            -- RGB border (kept for reference)
            -- active_border = { colors = { "rgba(ff0000ff)", "rgba(ff7f00ff)", "rgba(ffff00ff)", "rgba(00ff00ff)", "rgba(0000ffff)", "rgba(8B00ffff)" }, angle = 60 },
