-- Quickshell layers (bar, theme switcher, notifications, app launcher)
hl.layer_rule({
    name         = "quickshell",
    match        = { namespace = "quickshell" },
    blur         = true,
    ignore_alpha = 0,
    blur_popups  = true,
})

-- Floating, centered utility windows
local function float_rule(name, class, w, h, pin)
    hl.window_rule({
        name   = name,
        match  = { class = class },
        float  = true,
        size   = { w, h },
        center = true,
        pin    = pin,
    })
end

float_rule("pavucontrol",     ".*org.pulseaudio.pavucontrol.*", 700, 600, true)
float_rule("waypaper",        ".*waypaper.*",                   900, 700, true)
float_rule("blueman-manager", "blueman-manager",                800, 600)
float_rule("gnome-calculator", "org.gnome.Calculator",          700, 600)

-- XDG Desktop Portal
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")

-- QT (qt6ct covers Qt6 apps including Quickshell)
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
hl.env("QT_WAYLAND_DISABLE_WINDOWDECORATION", "1")
hl.env("QT_AUTO_SCREEN_SCALE_FACTOR", "1")
-- Quickshell resolves desktop-entry icons via QIcon::fromTheme. qt6ct
-- integration isn't always reliable for non-widget Qt apps, so set the icon
-- theme directly so the AppLauncher matches GTK apps like nwg-drawer.
hl.env("QT_ICON_THEME", "Colloid-Dark")

-- GDK
hl.env("GDK_SCALE", "1")

-- Toolkit Backend
hl.env("GDK_BACKEND", "wayland,x11,*")
hl.env("CLUTTER_BACKEND", "wayland")

-- Mozilla
hl.env("MOZ_ENABLE_WAYLAND", "1")

-- Ozone
hl.env("OZONE_PLATFORM", "wayland")
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "wayland")

hl.env("WLR_DRM_NO_ATOMIC", "1")

hl.env("GTK_THEME", "catppuccin-mocha-mauve-standard+default")

-- Per-app special workspaces. Each class floats at 1650x900, centered,
-- pinned to its own special workspace so toggle-or-launch.sh can find it.
-- Keep in sync with the `pinned` map in scripts/special-workspace-guard.sh.
--
-- NOTE: rerouting "rogue" windows that spawn onto a special workspace
-- (e.g. an app launched from the launcher while special:term is visible)
-- is handled by scripts/special-workspace-guard.sh — `workspace` matches
-- don't fire for windows being mapped, so the IPC listener does it
-- instead. Keep this comment so the next agent doesn't re-add a rule here.
local specials = {
    { class = "discord",        workspace = "discord" },
    { class = "spotify",        workspace = "spotify" },
    { class = "Docker Desktop", workspace = "docker" },
    { class = "GitHub Desktop", workspace = "github" },
    -- Drop-down terminal (Super + `) — kitty launched with --class=kitty-special
    { class = "kitty-special",  workspace = "term" },
    { class = "livepaper",      workspace = "livepaper" },
}

for _, s in ipairs(specials) do
    hl.window_rule({
        name      = "special-" .. s.workspace,
        match     = { class = s.class },
        float     = true,
        size      = { 1650, 900 },
        center    = true,
        workspace = "special:" .. s.workspace .. " silent",
    })
end
